// Deterministic resource-size correction, using the existing icon artwork.
// No title/game images are regenerated by this tool.
const fs=require('fs'),path=require('path'),{createRequire}=require('module');
const root=path.resolve(__dirname,'..');
const toolkit=process.env.WATCH_COMPAT_TOOLKIT||path.join(__dirname,'compat-toolkit/node_modules/aiot-toolkit');
const sharp=createRequire(path.join(path.resolve(toolkit),'package.json'))('sharp');
const source=process.argv[2],output=path.join(root,'src/common/logo.png');
if(!source)throw Error('Usage: node tools/resize-band-icon-v014.cjs PATH_TO_ORIGINAL_ICON');
(async()=>{
 const original=fs.readFileSync(path.resolve(source));
 const metadata=await sharp(original).metadata();
 if(metadata.width<128||metadata.height!==metadata.width)throw Error('Expected square original icon, at least 128 pixels');
 const encoded=await sharp(original).resize(128,128,{fit:'fill',kernel:'lanczos3'}).ensureAlpha().png({palette:false,compressionLevel:9}).toBuffer();
 // Paper's known-working PNG has no physical-resolution hint. Keep only the
 // pixel dimensions as the launcher size, without a DPI-dependent hint.
 const chunks=[encoded.subarray(0,8)];
 for(let offset=8;offset<encoded.length;){
  const length=encoded.readUInt32BE(offset),end=offset+length+12;
  if(end>encoded.length)throw Error('Invalid encoded PNG chunk');
  if(encoded.toString('ascii',offset+4,offset+8)!=='pHYs')chunks.push(encoded.subarray(offset,end));
  offset=end;
 }
 const icon=Buffer.concat(chunks);
 fs.writeFileSync(output,icon);
 console.log('BAND_ICON',JSON.stringify({width:128,height:128,bytes:icon.length,originalWidth:metadata.width}));
})().catch(e=>{console.error(e);process.exitCode=1;});
